<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= escapar_html($tituloPagina) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head>
<body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between"><h1 class="h2">Acompanhamento da produção</h1><a href="/painel" class="btn btn-outline-secondary">Painel</a></div>
<?php foreach (["RECEBIDO", "EM_PRODUCAO", "PRONTO", "ENTREGUE", "CANCELADO"] as $status): ?><section class="card border-0 shadow-sm mt-3"><div class="card-body"><h2 class="h5"><?= escapar_html($status) ?></h2><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Pedido</th><th>Cliente</th><th>Entrega</th><th>Prazo</th><th>Ações</th></tr></thead><tbody><?php $encontrou = false; foreach ($pedidos as $pedido): if ($pedido["status"] !== $status) { continue; } $encontrou = true; ?><tr><td>#<?= (int) $pedido["id"] ?></td><td><?= escapar_html($pedido["cliente"]) ?></td><td><?= escapar_html($pedido["data_entrega"] ?? "—") ?></td><td><?= $pedido["indicador_prazo"] === "atrasado" ? "<span class=\"badge text-bg-danger\">Atrasado</span>" : ($pedido["indicador_prazo"] === "proximo" ? "<span class=\"badge text-bg-warning\">Próximo</span>" : "—") ?></td><td><a class="btn btn-sm btn-outline-primary" href="/pedidos/detalhes?id=<?= (int) $pedido["id"] ?>">Detalhes</a><?php if (!in_array($status, ["ENTREGUE", "CANCELADO"], true)): ?><form class="d-inline" method="post" action="/pedidos/status"><input type="hidden" name="token_csrf" value="<?= escapar_html($tokenCsrf) ?>"><input type="hidden" name="id_pedido" value="<?= (int) $pedido["id"] ?>"><select class="form-select form-select-sm d-inline w-auto" name="status"><option value="EM_PRODUCAO">Em produção</option><option value="PRONTO">Pronto</option><option value="ENTREGUE">Entregue</option></select><button class="btn btn-sm btn-primary">Atualizar</button></form><?php if ($podeCancelar): ?><form class="d-inline" method="post" action="/pedidos/cancelar"><input type="hidden" name="token_csrf" value="<?= escapar_html($tokenCsrf) ?>"><input type="hidden" name="id_pedido" value="<?= (int) $pedido["id"] ?>"><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif; ?><?php endif; ?></td></tr><?php endforeach; if (!$encontrou): ?><tr><td colspan="5" class="text-secondary">Nenhum pedido neste status.</td></tr><?php endif; ?></tbody></table></div></div></section><?php endforeach; ?></main></body></html>
